def parse_text(text: str, text_format: type[TextFormatT] | Omit, *, phase: str | None) -> TextFormatT | None:
    """Parse final-answer text, retaining legacy behavior for messages without a phase.

    Explicit phases other than `final_answer` are not structured results. Leave
    their text unparsed, including phases introduced by future API versions.
    Both completed responses and streamed text-done events use this rule.
    """
    if phase is not None and phase != "final_answer":
        return None

    if not is_given(text_format):
        return None

    if is_basemodel_type(text_format):
        return cast(TextFormatT, model_parse_json(text_format, text))

    if is_dataclass_like_type(text_format):
        if PYDANTIC_V1:
            raise TypeError(f"Non BaseModel types are only supported with Pydantic v2 - {text_format}")

        return pydantic.TypeAdapter(text_format).validate_json(text)

    raise TypeError(f"Unable to automatically parse response format type {text_format}")


def get_input_tool_by_name(
    *, input_tools: Iterable[ToolParam], name: str, namespace: str | None = None
) -> FunctionToolParam | ToolFunction | None:
    if namespace is not None:
        input_tools = list(input_tools)
        for tool in input_tools:
            if tool["type"] == "namespace" and tool["name"] == namespace:
                for nested_tool in tool["tools"]:
                    if nested_tool["type"] == "function" and nested_tool["name"] == name:
                        return nested_tool
                return None
